/*
 * Hằng số breakpoint mobile/desktop đặt trong namespace Helper.Env để tránh
 * collide với global var của theme/plugin/lib khác (Bootstrap, jQuery plugin
 * có thể trùng tên MOBILE_MAX). init.js load TRƯỚC Helper.js trong bundle nên
 * phải tự khởi tạo skeleton Helper/Helper.Env (idempotent với `||`).
 *
 * - Mobile: viewport <= Helper.Env.MOBILE_MAX (768px)
 * - Desktop: viewport >= Helper.Env.DESKTOP_MIN (769px)
 *
 * Trong template literal sinh CSS, dùng `${Helper.Env.MOBILE_MAX}` / `${Helper.Env.DESKTOP_MIN}`.
 */
var Helper = Helper || {};
Helper.Env = Helper.Env || {};
Helper.Env.MOBILE_MAX = 768;
Helper.Env.DESKTOP_MIN = 769;

