/*
 * Helper.Env.isOnMobile — kiểm tra viewport hiện tại có thuộc dải mobile không.
 * Dùng Helper.Env.MOBILE_MAX (khai báo trong init.js, default 768) để mọi module
 * FE chia sẻ một mốc duy nhất. Fallback 768 nếu Helper.Env.MOBILE_MAX chưa init
 * (load trước init.js — thực tế không xảy ra trong bundle hiện tại).
 */
Helper.Env.isOnMobile = function () {
    var max = (Helper.Env && typeof Helper.Env.MOBILE_MAX === "number") ? Helper.Env.MOBILE_MAX : 768;
    return window.innerWidth <= max;
};

/*
 * TASK00658 — ngưỡng "mobile" của MỘT menu cụ thể (không phải mốc toàn cục).
 *
 * Mặc định trả đúng Helper.Env.MOBILE_MAX (768) cho MỌI menu kind — tức hành vi cũ không đổi 1 ly.
 * Riêng SECTION_DESKTOP_MEGAMENU có setting per-menu `desktopMegaBreakpoint`: merchant hạ xuống
 * (vd 600) thì menu ĐÓ vẫn ở chế độ desktop trong khoảng (breakpoint, 768]. Mọi logic gate
 * "desktop hay mobile" của CHÍNH menu đó phải hỏi hàm này thay vì Helper.Env.isOnMobile() toàn cục,
 * nếu không sẽ lệch pha: bar hiện dạng desktop nhưng hover/ESC/CSS hover-style lại tưởng đang mobile.
 *
 * @param {Object} setting  - setting object của menu (naviItem.data.setting)
 * @param {Number|String} menuKind
 * @returns {Number} ngưỡng px, dưới hoặc bằng mức này coi là mobile
 */
Helper.Env.mobileMaxOfMenu = function (setting, menuKind) {
    var max = (Helper.Env && typeof Helper.Env.MOBILE_MAX === "number") ? Helper.Env.MOBILE_MAX : 768;
    if (typeof NAVIGLOBAL === "undefined") return max;
    if (menuKind != NAVIGLOBAL["MENU_KINDS"]["SECTION_DESKTOP_MEGAMENU"]) return max;
    var bp = setting ? parseInt(setting["desktopMegaBreakpoint"], 10) : NaN;
    /* bp < 1 (0, số âm — form chặn min=200 nhưng Automation API/DB ghi thẳng thì không) sẽ sinh ra
       `@media (min-width:-4px)` — media feature INVALID khiến trình duyệt bỏ NGUYÊN khối, kéo theo
       mobileDisplay/desktopDisplay mất tác dụng. Rơi về mốc mặc định thay vì tạo CSS hỏng. */
    return (isNaN(bp) || bp < 1) ? max : bp;
};

/* Bản boolean của mobileMaxOfMenu — dùng thay Helper.Env.isOnMobile() ở nơi biết rõ đang xử lý menu nào. */
Helper.Env.isOnMobileForMenu = function (setting, menuKind) {
    return window.innerWidth <= Helper.Env.mobileMaxOfMenu(setting, menuKind);
};

/*
 * Dành cho listener TOÀN CỤC không gắn với 1 menu cụ thể (vd phím ESC đóng dropdown): có menu
 * Desktop Mega nào đang ở chế độ desktop nhờ breakpoint riêng hay không. Không có menu nào như vậy
 * → trả false và caller giữ nguyên hành vi cũ theo Helper.Env.isOnMobile().
 */
Helper.Env.hasMegaMenuInDesktopMode = function () {
    if (typeof NAVIGLOBAL === "undefined") return false;
    if (!window.navimanData || !Array.isArray(window.navimanData)) return false;
    var mkD = NAVIGLOBAL["MENU_KINDS"]["SECTION_DESKTOP_MEGAMENU"];
    for (var i = 0; i < window.navimanData.length; i++) {
        var n = window.navimanData[i];
        if (n.menuKind != mkD) continue;
        var st = (n["data"] && n["data"]["setting"]) ? n["data"]["setting"] : null;
        if (!Helper.Env.isOnMobileForMenu(st, mkD)) return true;
    }
    return false;
};

Helper.Env.isBackendMode = function () {
    if (typeof DEPLOY_ENVIROIMENT != 'undefined')
        if (DEPLOY_ENVIROIMENT == "DESIGNING") {
            return true;
        }
    return false;
};

Helper.Env.isInternalUsed = function ( embed_id ) {

    if( embed_id == "SF-3142083120" )
        return true;
    return false;
};


/**
 * Helper.Env.checkBrowserSupport
 * -------------------------------------------
 * Kiểm tra và log các tính năng trình duyệt quan trọng (cookie, localStorage, sessionStorage, serviceWorker, fetch, WebSocket).
 * Chỉ kiểm tra 1 lần trong 1 phiên để tránh log lặp.
 * Dùng để hỗ trợ debug các vấn đề liên quan tới trình duyệt không hỗ trợ đủ các tính năng cần thiết cho Navi+.
 */
Helper.Env.checkBrowserSupport = function () {
    // Kiểm tra nếu trạng thái đã được lưu trong window
    if (window._browserSupportChecked) {
        return;
    }

    // Thực hiện kiểm tra
    const supportStatus = {
        cookies: navigator.cookieEnabled,
        localStorage: typeof localStorage !== 'undefined',
        sessionStorage: typeof sessionStorage !== 'undefined',
        serviceWorkers: 'serviceWorker' in navigator,
        fetchAPI: typeof fetch === 'function',
        webSockets: 'WebSocket' in window
    };

    // Log trạng thái thành một dòng
    const statusLine = Object.entries(supportStatus)
        .map(([feature, isSupported]) => `${feature}: ${isSupported ? 'Supported' : 'Not Supported'}`)
        .join(', ');
        navidebug.log(statusLine);

    // Lưu trạng thái vào window để tránh gọi lại
    window._browserSupportChecked = true;
};

/**
 * Kiểm tra tính hợp lệ của embed dựa trên domain hiện tại.
 * Quy trình:
 *  1. Lấy domain shop từ section_setting['shop'] (bỏ www, port, khoảng trắng).
 *  2. Lấy domain hiện tại từ window.location.hostname (bỏ www, port, khoảng trắng).
 *  3. So sánh hai domain:
 *     - Nếu khác nhau, trả về true (embed KHÔNG hợp lệ).
 *     - Nếu giống nhau, trả về false (embed hợp lệ).
 * @param {Object} section_setting - Cấu hình section hiện tại, cần có thuộc tính 'shop'.
 * @returns {boolean} true nếu domain embed khác domain shop (không hợp lệ), ngược lại trả về false.
 */
Helper.Env.isInvalidEmbed = function( section_setting ) {
    if( this.isBackendMode() ) return false;

    // Wix: shop=siteId không phải domain thật → embed luôn hợp lệ (skip domain check)
    if( section_setting['env'] === 'wix' ) {
        return false;
    }

    // WordPress SSO: shop là "wp_TOKEN", không phải domain thật → bỏ qua domain check
    if( WpMarket.isActive(section_setting['env']) ) {
        return false;
    }

    var shop = navistart.normalizeDomainSync(section_setting['shop']);
    var currentDomain = navistart.normalizeDomainSync(window.location.hostname);

    if( shop != currentDomain )
        return true;

    return false;
}

/**
 * Dọn dẹp phần tử: gỡ các attribute và class chỉ định.
 * @param {Element} el - Phần tử cần xử lý
 * @param {Object} opts - { attr: ["data-bs-toggle", ...], class: ["_navi_loading", ...] }
 */
Helper.HTML.cleanupElement = function(el, opts) {
  opts = opts || {};
  var attrs = opts.attr || opts.attrs || [];
  var classes = opts.class || opts.classes || [];
  if (!Array.isArray(attrs)) attrs = [attrs];
  if (!Array.isArray(classes)) classes = [classes];
  attrs.forEach(function(name) {
    if (el.hasAttribute(name)) el.removeAttribute(name);
  });
  classes.forEach(function(cls) {
    if (el.classList.contains(cls)) el.classList.remove(cls);
  });
  return el;
};

/**
 * Gỡ toàn bộ event listeners: clone phần tử và thay thế, phần tử mới không còn listener.
 * @param {Element} element - Phần tử cần gỡ listener
 * @returns {Element} Phần tử mới (đã thay thế)
 */
Helper.HTML.removeAllEventListeners = function(element) {
  var newElement = element.cloneNode(true);
  element.parentNode.replaceChild(newElement, element);
  return newElement;
};

/**
 * Gỡ listener ở tất cả các con (1 level từ CSS selector). Con sâu hơn có click thì ko xử lý được.
 * Loại bỏ attr on:*, on:* (Svelte), aria-expanded; clone node để gỡ addEventListener; chặn onclick.
 */
Helper.HTML.removeChildrenListeners = function(newEl) {
  var allChildren = newEl.querySelectorAll('*');
  allChildren.forEach(function(child) {
    Array.from(child.attributes).forEach(function(attr) {
      if (attr.name.startsWith('on') || attr.name.startsWith('on:') || attr.name === 'aria-expanded')
        child.removeAttribute(attr.name);
    });
    var clone = child.cloneNode(true);
    clone.setAttribute('onclick', 'event.preventDefault();return;');
    child.parentNode.replaceChild(clone, child);
  });
};

/**
 * Helper.HTML.parsePaddingMargin( paddingVars )
 *
 * Parse chuỗi padding/margin nhập tự do thành object { top, right, bottom, left }.
 * Tuân theo CSS shorthand rule: 1 / 2 / 3 / 4 giá trị.
 *
 * Input hỗ trợ:
 *   "24"                → top=right=bottom=left=24
 *   "24 16"             → top=bottom=24, right=left=16
 *   "24 16 8"           → top=24, right=left=16, bottom=8
 *   "24 16 8 4"         → top=24, right=16, bottom=8, left=4
 *   "24px 16pt 8em 4"   → strip đơn vị, convert về số
 *   "24  16  8"         → multiple spaces OK
 *   "24, 16; 8"         → dấu phẩy/chấm phẩy OK
 *   "24 16 | 8 4"       → format mobile|desktop: chọn theo window.innerWidth
 *
 * Backward-compat: hàm đã tồn tại trước, chỉ sửa nội dung.
 * Caller (uigen_drawNav.js, generateMenu_Children.js, uigen_generateCSS.js) không đổi signature.
 */
Helper.HTML.parsePaddingMargin = function (paddingVars) {
    var padding = {
        "top": 0,
        "right": 0,
        "bottom": 0,
        "left": 0,
    };

    if( paddingVars == null || String(paddingVars).trim() == "" )
        return padding;

    // Hỗ trợ format "mobile | desktop" — platformValue chọn phần phù hợp theo viewport
    paddingVars = platformValue(String(paddingVars));

    // Chuẩn hoá: strip đơn vị CSS (px, pt, em, rem, %, ...), thay phẩy/chấm phẩy bằng space
    paddingVars = String(paddingVars)
        .replace(/[a-z%]+/gi, " ")
        .replace(/[,;]/g, " ");

    // Split theo whitespace (bắt multiple spaces), lọc empty, convert sang số
    var values = paddingVars.split(/\s+/).filter(function(v){ return v !== ""; }).map(Number);

    // Bỏ NaN phòng trường hợp còn ký tự lạ sau khi strip
    values = values.filter(function(v){ return !isNaN(v); });

    if (values.length === 0) return padding;

    // Gán theo CSS shorthand: top / right / bottom / left
    switch (values.length) {
        case 1:
            padding.top = padding.right = padding.bottom = padding.left = values[0];
            break;
        case 2:
            padding.top = padding.bottom = values[0];
            padding.right = padding.left = values[1];
            break;
        case 3:
            padding.top    = values[0];
            padding.right  = padding.left = values[1];
            padding.bottom = values[2];
            break;
        default: // 4 trở lên — chỉ lấy 4 giá trị đầu
            padding.top    = values[0];
            padding.right  = values[1];
            padding.bottom = values[2];
            padding.left   = values[3];
            break;
    }
    return padding;
};


Helper.HTML.formatPaddingTRBL = function( padding ) {
    if( padding.top == 0 & padding.right == 0 & padding.bottom == 0 & padding.left == 0 )
        return "";
    return ' padding: '+ padding.top +'px '+ padding.right +'px '+ padding.bottom +'px '+ padding.left +'px; '
}

Helper.HTML.formatMarginTRBL = function( margin ) {
    if( margin.top == 0 & margin.right == 0 & margin.bottom == 0 & margin.left == 0 )
        return "";
    return ' margin: '+ margin.top +'px '+ margin.right +'px '+ margin.bottom +'px '+ margin.left +'px; '
}

Helper.HTML.addStyleToMenu = function(naviman_appItem, inputStyle) {
    // data-navi-style: marker để teardownRenderedMenus() (uigen_func.js.php) nhận diện & xoá hết
    // các thẻ <style> Navi tự chèn 'beforebegin' khi vẽ lại — cùng cơ chế fix rò rỉ với
    // uigen_generateCSS.js (generateCSS_Advance()/generateCSS()), xem TASK00590-todo.md.
    let html = '<style data-navi-style="1"> ';
    html += inputStyle;
    html += ' </style>';
    naviman_appItem.insertAdjacentHTML('beforebegin', html);
}

Helper.HTML.addStyleToMenuAfterEnd = function(naviman_appItem, inputStyle) {
    let html = '<style> ';
    html += inputStyle;
    html += ' </style>';
    naviman_appItem.insertAdjacentHTML('afterend', html);
}

Helper.HTML.addStyleToHeader = function(styles) {
    var css = document.createElement('style');
    css.type = 'text/css';
    if (css.styleSheet)
        css.styleSheet.cssText = styles;
    else
        css.appendChild(document.createTextNode(styles));
    document.getElementsByTagName("head")[0].appendChild(css);
}

Helper.HTML.clearCSS_JS =  function (css) {
    if (typeof css == 'undefined')
        return "";
    css = css.trim();
    css = css.strReplace('<script>', '');
    css = css.strReplace('</script>', '');
    css = css.strReplace('<style>', '');
    css = css.strReplace('</style>', '');
    return css;
};

Helper.HTML.isExternalUrl = function(file_path) {
    if (file_path.length > 5) { // Kiểm tra độ dài tối thiểu
        return file_path.startsWith('http://') || file_path.startsWith('https://');
    }
    return false;
};

/*
Phương án giải quyết: Tính một lần chiều cao của ulLength và lưu vào attribute.
1. Hiện ulChildrent là cha của các li.child 
2. Tính offsetHeight và cộng vào ulLength
3. Lưu ulLength vào attribute
4. Khi hiển thị lại thì không cần tính toán lại (nếu có)
    */
Helper.HTML.getULLength = function(ulChildrent) {
    var ulLength = 0;
    if (ulChildrent.getAttribute('ulLength')) 
        ulLength = ulChildrent.getAttribute('ulLength');
    else {
        ulLength = 8; // Một con số bốc thuốc
        let liChildrent = ulChildrent.querySelectorAll("li.child");
        for (let i = 0; i < liChildrent.length; i++) 
            ulLength += liChildrent[i].offsetHeight;
        ulChildrent.setAttribute('ulLength', ulLength);
    }
    return ulLength;
}




Helper.hasVisibleSlideMenu = function() {
    var items = document.querySelectorAll('.naviItem.CONTEXT_SLIDE');
    for (var i = 0; i < items.length; i++) {
        if (window.getComputedStyle(items[i]).visibility === "visible")
            return true;
    }
    return false;
};

/**
 * Kiểm tra L2 (ul.children) có còn coi là “đang mở” theo cùng tiêu chí với showLevel2Items (uigen_gotoUrl):
 * is_showing = ["block", "flex"].includes(ul.style.display) — chỉ inline, không dùng computed một mình.
 * Tránh lệch: closeAllDropdowns đã set style.display = none nhưng animation/opacity khiến getComputedStyle vẫn
 * như đang hiện → handleTouchOutside gọi showLevel2Items nhánh mở và bật lại tabbar L2.
 *
 * @param {Element|null|undefined} menuItem - thường là window._openingMenuItem
 * @returns {boolean}
 */
Helper.isOpeningLevel2UlStillVisible = function (menuItem) {
    if (!menuItem || !menuItem.querySelector) {
        return false;
    }
    var subUl = menuItem.querySelector("ul.children");
    if (!subUl || !subUl.style) {
        return false;
    }
    var sd = subUl.style.display ? String(subUl.style.display).trim().toLowerCase() : "";
    if (sd !== "block" && sd !== "flex") {
        return false;
    }
    try {
        var cs = window.getComputedStyle(subUl);
        return cs.display !== "none" && cs.visibility !== "hidden" && parseFloat(cs.opacity || "1") > 0;
    } catch (e) {
        return false;
    }
};

/**
 * Chặn handleTouchOutsideAllMenus trong vài trăm ms sau clickToElement (theme thường bắn click thật bất đồng bộ).
 * Bổ sung cho cờ _suppressOutsideMenuClickForThemeAutomation (chỉ khớp dispatch đồng bộ).
 *
 * @param {number} [ms=450]
 */
Helper.extendThemeAutomationOutsideSuppression = function (ms) {
    var t = typeof ms === "number" && ms > 0 ? ms : 450;
    Helper._suppressOutsideMenuUntilMs = Date.now() + t;
};

Helper.hideNaviOverlay = function () {
    var list = document.getElementsByClassName("naviman_app_overlay");
    if (!list || !list.length) return;
    for (var i = 0; i < list.length; i++) {
        var el = list[i];
        el.style.display = "none";
        el.style.pointerEvents = "none";
        el.style.visibility = "hidden";
    }
}

Helper.showNaviOverlay = function () {
    var list = document.getElementsByClassName("naviman_app_overlay");
    if (!list || !list.length) return;
    for (var j = 0; j < list.length; j++) {
        var elShow = list[j];
        elShow.style.display = "block";
        elShow.style.pointerEvents = "";
        elShow.style.visibility = "";
    }

/*    var body = document.getElementsByTagName('body')[0];
    body.style.overflow = 'hidden';
*/
}

Helper.closeAllDropdowns = function () {
    ZIndex.restoreAllElementsFromMax();
    ZIndex.restoreAllZIndexForOtherMega(); // hồi phục z-index đã hạ tạm của desktop mega menu khác
    ZIndex.restoreAllSectionZIndex();
    // TASK00193: đóng L3 tabbar đã port (ở host) — trả về chỗ cũ + ẩn
    Menu.Sticky._restoreAllPortedLevel3();

    document.querySelectorAll('.naviman_app ul.children').forEach((item) => {
        item.style.display = "none";
    });
    document.querySelectorAll('.naviman_app span.arrow').forEach((item) => {
        item.style.display = "none";
    });

    document.querySelectorAll('.naviItem .menu-expand, .naviItem .menu-expand-level1, .naviItem .menu-expand-level2').forEach((item) => {
        item.classList.remove('menu-expand', 'menu-expand-level1', 'menu-expand-level2');
    });

    /* closeAllDropdowns là đường đóng CATCH-ALL (click ngoài/ESC/resize/menu khác mở) — nếu không gỡ
       navi-level2-open/navi-level3-open ở đây, level 1 (ul.navigation) bị kẹt visibility:hidden
       (CSS marker cho slide-horizontal) dù ul.children đã display:none, menu trông như biến mất hẳn. */
    document.querySelectorAll('.naviItem.CONTEXT_SLIDE.navi-level2-open, .naviItem.CONTEXT_SLIDE.navi-level3-open').forEach((item) => {
        item.classList.remove('navi-level2-open', 'navi-level3-open');
    });

    /* Khôi phục pointer-events trigger overlay slide menu (đã tắt khi mega mở — MenuMega.js).
       closeAllDropdowns là đường đóng CATCH-ALL (click ngoài / ESC / resize / menu khác mở) KHÔNG
       đi qua restoreSectionZIndexForDesktopMega → nếu không gọi ở đây, overlay kẹt pointer-events:none
       → slide trigger chết sau khi mega đóng kiểu này. menu-expand vừa gỡ ở trên nên restore
       (DOM-check) thấy 0 mega mở → khôi phục đúng (TASK00366, 2026-07-06). */
    if (typeof Menu !== "undefined" && Menu.Mega && Menu.Mega._restoreTriggerOverlays)
        Menu.Mega._restoreTriggerOverlays();

    /* Restore overflow:visible đã set inline cho Safari subDir 2/3 fix */
    document.querySelectorAll('.naviItem.CONTEXT_SLIDE').forEach(function(m) {
        if (m._naviSafariSubDirScrollTop !== undefined) {
            m.style.removeProperty("overflow");
            m.scrollTop = m._naviSafariSubDirScrollTop;
            delete m._naviSafariSubDirScrollTop;
        }
    });

    document.querySelectorAll('.naviman_app ul.children').forEach((item) => {
        item.style.height = "initial";
    });

    document.querySelectorAll('.naviman_app li.overlay-container').forEach((item) => {
        item.remove();
    });

    Helper.hideNaviOverlay();

    /* Mở khoá scroll trang nếu mobile megamenu đang lock (tránh kẹt scroll khi đóng qua overlay). */
    Helper_lockBodyScroll(false);

    /* Đóng hết dropdown: mở khóa overlay_global nếu không còn slide CONTEXT_SLIDE
     * (slide vẫn dùng chung overlay_global — không được tắt khi slide còn mở). */
    if (!Helper.hasVisibleSlideMenu()) {
        Helper.hideNaviOverlayGlobal();
    }

}

/*
 * Đóng submenu level 2 đang mở, tracked qua window._openingMenuItem/_openingMenuKind/_openingEmbedId.
 * Trích từ Finalizer.Event.handleTouchOutsideAllMenus (case "click ra ngoài menu" đã chạy đúng) để
 * dùng lại y hệt cho leaf-click bubble lên từ gotoUrl() (TASK00493 — Nick báo "menu đang mở, bấm gì
 * cũng phải đóng level 2", 2 case còn thiếu: bấm item khác trong submenu / bấm sang item level-1 khác).
 * - Nếu DOM còn coi là "đang mở" đúng nghĩa (isOpeningLevel2UlStillVisible) → toggle đóng qua
 *   showLevel2Items (có animation, giống mọi chỗ đóng khác trong app).
 * - Nếu state đã lệch (DOM đã ẩn nhưng biến global chưa reset) → reset state + closeAllDropdowns() thô.
 * - Nếu không tracking gì đang mở → vẫn gọi closeAllDropdowns() (idempotent, dọn các trường hợp lệch khác).
 */
Helper.closeCurrentOpeningSubmenu = function() {
    if (window._openingMenuItem && window._openingMenuKind && window._openingEmbedId) {
        var subStillOpen = typeof Helper.isOpeningLevel2UlStillVisible === "function"
            ? Helper.isOpeningLevel2UlStillVisible(window._openingMenuItem)
            : false;
        if (!subStillOpen) {
            if (typeof ZIndex !== "undefined" && typeof ZIndex.resetOpeningMenuState === "function") {
                ZIndex.resetOpeningMenuState();
            } else {
                delete window._openingMenuItem;
                delete window._openingMenuKind;
                delete window._openingEmbedId;
            }
            Helper.closeAllDropdowns();
            return;
        }
        naviman.showLevel2Items(window._openingMenuItem, window._openingMenuKind, window._openingEmbedId);
    } else {
        Helper.closeAllDropdowns();
    }
};

/*
 * Đóng level 2/3 của tất cả menu khác (embed_id khác với currentEmbedId).
 * Dùng để đảm bảo khi bất kỳ menu nào mở submenu, các menu còn lại về level 1.
 * Không đụng đến menu có id == currentEmbedId.
 *
 * @param {string} currentEmbedId - embed_id của menu đang mở submenu
 */
Helper.closeDropdownsOfOtherMenus = function(currentEmbedId) {
    document.querySelectorAll('.naviman_app .naviItem').forEach(function(naviItem) {
        if (naviItem.id === currentEmbedId) return;

        naviItem.querySelectorAll('ul.children').forEach(function(ul) {
            ul.style.display = "none";
            ul.style.height = "initial";
        });
        naviItem.querySelectorAll('span.arrow').forEach(function(arrow) {
            arrow.style.display = "none";
        });
        naviItem.querySelectorAll('.menu-expand, .menu-expand-level1, .menu-expand-level2').forEach(function(el) {
            el.classList.remove('menu-expand', 'menu-expand-level1', 'menu-expand-level2');
        });
        naviItem.querySelectorAll('li.overlay-container').forEach(function(el) {
            el.remove();
        });
        naviItem.querySelectorAll('.slide-horizontal-level3-wrapper').forEach(function(wrapper) {
            wrapper.style.display = "none";
        });
        /* Cùng lý do closeAllDropdowns() — gỡ marker bền navi-level2-open/navi-level3-open của
           MENU KHÁC (không phải currentEmbedId) khi bị đóng ở đây, tránh kẹt level 1 ẩn vĩnh viễn. */
        naviItem.classList.remove('navi-level2-open', 'navi-level3-open');
    });

    /* Tính whitelist các ancestor đã raise của menu hiện tại để KHÔNG restore chúng
       khi đóng các menu khác. Dùng _getElementsToPushZIndex (cùng hàm dùng khi raise)
       để match đúng identity, tránh bug level 2 mega menu rơi z-index khi mở level 3.
       Anchor: ưu tiên li level 1 đang expand; fallback naviItem root. */
    var keepEls = [];
    var currentMenu = currentEmbedId ? document.getElementById(currentEmbedId) : null;
    if (currentMenu && typeof Menu !== "undefined" && Menu.Mega &&
        typeof Menu.Mega._getElementsToPushZIndex === "function") {
        var anchor = currentMenu.querySelector('li.is-parent-top.menu-expand-level1') ||
                     currentMenu.querySelector('li.is-parent-top.menu-expand') ||
                     currentMenu.querySelector('li.menu-expand') ||
                     currentMenu.querySelector('li.is-parent-top') ||
                     currentMenu;
        keepEls = Menu.Mega._getElementsToPushZIndex(anchor) || [];
    }
    ZIndex.restoreElementsFromMaxExcept(keepEls);

    ZIndex.restoreAllSectionZIndex();

    /* Mega vừa bị đóng vì menu khác mở → khôi phục trigger overlay nếu không còn mega nào mở
       (DOM-check tự-sửa; nếu menu đang mở là mega thì raise() của nó đã/đang suppress lại). */
    if (typeof Menu !== "undefined" && Menu.Mega && Menu.Mega._restoreTriggerOverlays)
        Menu.Mega._restoreTriggerOverlays();
};

/*
 * -------------------------------------------------------------------------
 * Theme automation — open:clickTo / open:focusTo / clickToElement / focusToElement
 * -------------------------------------------------------------------------
 * Mục đích: đóng menu Navi+ (slide, L2/L3, overlay) trước khi kích hoạt UI theme (search, cart, …),
 * tránh xung đột z-index và “click ngoài” xử lý sai cùng một nhịp.
 *
 * - _suppressOutsideMenuClickForThemeAutomation: cờ tạm bật khi bắn synthetic events (PublicFuncs.clickToElement).
 * - traceOpenAction: log có thể bật qua NAVI_TRACE_OPEN_SCREEN / ?navi_trace_open=1 / localStorage.
 * - runAfterClosingMenusForOpenAction + closeMenusBeforeOpenInteractionPromise: chuỗi đóng menu rồi gọi callback.
 * - ensureOverlaysDismissedBeforeThemeClick: sau skipPrepareMenus, ép ẩn overlay + chờ rAF (paint).
 * - isOpeningLevel2UlStillVisible: khớp inline display với showLevel2Items (tránh mở lại L2).
 * - extendThemeAutomationOutsideSuppression / _suppressOutsideMenuUntilMs: chặn click document sau automation.
 * -------------------------------------------------------------------------
 */

/**
 * Đặt true trong lúc clickToElement (PublicFuncs) bắn chuỗi pointer/mouse/click giả lập lên element theme,
 * để Finalizer.Event.handleTouchOutsideAllMenus bỏ qua (tránh đóng/toggle menu Navi+ cùng tick).
 */
Helper._suppressOutsideMenuClickForThemeAutomation = false;

/** Timestamp (ms): đến thời điểm này thì bỏ qua xử lý “click ngoài menu” (theme automation). */
Helper._suppressOutsideMenuUntilMs = 0;

/**
 * Trace luồng open:clickTo / open:focusTo — luôn ghi console [Navi open].
 * Hiện snackbar (miniSnackbar) khi bật: window.NAVI_TRACE_OPEN_SCREEN === true,
 * hoặc ?navi_trace_open=1 trên URL, hoặc localStorage NAVI_TRACE_OPEN_SCREEN === "1".
 *
 * @param {string} msg
 * @param {string} [type] - info|warning|success|error cho snackbar
 */
Helper.traceOpenAction = function (msg, type) {
    var line = "[Navi open] " + msg;
    if (typeof console !== "undefined" && console.log) {
        console.log(line);
    }
    var showScreen = false;
    try {
        if (window.NAVI_TRACE_OPEN_SCREEN === true) showScreen = true;
        else if (window.NAVI_TRACE_OPEN_SCREEN === false) showScreen = false;
        else if (typeof location !== "undefined" && location.search && /[?&]navi_trace_open=1(?:&|$)/.test(location.search)) showScreen = true;
        else if (window.localStorage && localStorage.getItem("NAVI_TRACE_OPEN_SCREEN") === "1") showScreen = true;
    } catch (e) {
        showScreen = false;
    }
    if (showScreen && typeof miniSnackbar !== "undefined" && miniSnackbar && typeof miniSnackbar.show === "function") {
        miniSnackbar.show(line, 4000, type || "info");
    }
};

/*
 * Chuẩn bị UI trước khi gọi clickToElement / focusToElement (và theme helper dùng chúng):
 * Bước 1 — Đóng mọi slide CONTEXT_SLIDE đang hiển thị (animation giống nút đóng/overlay).
 * Bước 2 — Đóng dropdown giống bấm overlay_global (Finalizer.Event.closeByOverlayGlobalForNonSlideMenus):
 *          hideAllLevel3Items + khôi phục z-index đang mở + closeAllDropdowns + gỡ khóa scroll + is-open;
 *          tránh chỉ gọi closeAllDropdowns (thiếu restore ZIndex / state Tabbar khi đang mở level 3).
 * Bước 3 — gọi doneCallback (vd. mở cart theme, focus ô search).
 */
Helper.runAfterClosingMenusForOpenAction = function (doneCallback, debugLabel) {
    var label = debugLabel || "click/focus theme";
    if (typeof doneCallback !== "function") return;

    var step2CloseDropdownsAndFinish = function () {
        Helper.traceOpenAction(label + " — bước2: hideAllLevel3 + đóng giống overlay → gọi callback");

        if (typeof window !== "undefined" && window.naviman && typeof window.naviman.hideAllLevel3Items === "function") {
            window.naviman.hideAllLevel3Items();
            Helper.traceOpenAction(label + " — hideAllLevel3Items đã gọi");
        } else {
            Helper.traceOpenAction(label + " — không có naviman.hideAllLevel3Items", "warning");
        }

        if (typeof Finalizer !== "undefined" && Finalizer.Event && typeof Finalizer.Event.closeByOverlayGlobalForNonSlideMenus === "function") {
            Finalizer.Event.closeByOverlayGlobalForNonSlideMenus();
            Helper.traceOpenAction(label + " — closeByOverlayGlobalForNonSlideMenus đã gọi");
        } else {
            Helper.traceOpenAction(label + " — fallback (không có Finalizer.Event)", "warning");
            if (typeof ZIndex !== "undefined" && typeof ZIndex.restoreAndResetOnClose === "function") {
                ZIndex.restoreAndResetOnClose();
            }
            Helper.closeAllDropdowns();
            if (typeof Helper_lockBodyScroll === "function") {
                Helper_lockBodyScroll(false);
            }
            var _ogFallback = document.querySelector(".naviman_app_overlay_global");
            if (_ogFallback) {
                _ogFallback.classList.remove("is-open");
            }
        }

        Helper.traceOpenAction(label + " — bước3: chạy click/focus theme");
        doneCallback();
    };

    var slideEls = document.querySelectorAll(".naviItem.CONTEXT_SLIDE");
    var visibleSlides = [];
    if (typeof Finalizer !== "undefined" && Finalizer.Event && typeof Finalizer.Event.getVisibleSlideMenus === "function") {
        visibleSlides = Finalizer.Event.getVisibleSlideMenus(slideEls);
    } else {
        for (var si = 0; si < slideEls.length; si++) {
            if (window.getComputedStyle(slideEls[si]).visibility === "visible") visibleSlides.push(slideEls[si]);
        }
    }

    if (visibleSlides.length === 0) {
        Helper.traceOpenAction(label + " — bước1: không có CONTEXT_SLIDE mở → vào đóng dropdown");
        step2CloseDropdownsAndFinish();
        return;
    }

    Helper.traceOpenAction(label + " — bước1: đóng " + visibleSlides.length + " slide (CONTEXT_SLIDE) trước");
    var remaining = visibleSlides.length;
    var onOneSlideClosed = function () {
        if (--remaining <= 0) step2CloseDropdownsAndFinish();
    };
    for (var vi = 0; vi < visibleSlides.length; vi++) {
        (function (panel) {
            if (typeof Finalizer !== "undefined" && Finalizer.Event && typeof Finalizer.Event._closeSlideMenuItem === "function") {
                Finalizer.Event._closeSlideMenuItem(panel, onOneSlideClosed);
            } else if (typeof Animation !== "undefined" && typeof Animation.hamburgerClose === "function") {
                Animation.hamburgerClose(panel, { durationMs: 300, doneCallback: onOneSlideClosed });
            } else {
                onOneSlideClosed();
            }
        })(visibleSlides[vi]);
    }
};

/*
 * Phiên bản Promise của runAfterClosingMenusForOpenAction (dùng trong clickToElement async).
 */
Helper.closeMenusBeforeOpenInteractionPromise = function (debugLabel) {
    return new Promise(function (resolve) {
        Helper.runAfterClosingMenusForOpenAction(resolve, debugLabel);
    });
};

Helper.lockBodyScroll = function(isLock) {
  Helper_lockBodyScroll(isLock);
};

Helper.showNaviOverlayGlobal = function () {    
    const overlayGlobal = document.querySelector('.naviman_app_overlay_global');
    if (!overlayGlobal) return;
    overlayGlobal.style.pointerEvents = "";
    overlayGlobal.style.visibility = "";
    overlayGlobal.style.display = "";
    overlayGlobal.classList.add('is-open');
    Helper.lockBodyScroll(true);
}

Helper.hideNaviOverlayGlobal = function () {
    const overlayGlobal = document.querySelector('.naviman_app_overlay_global');
    if (!overlayGlobal) return;
    overlayGlobal.classList.remove('is-open');
    overlayGlobal.style.display = "none";
    overlayGlobal.style.pointerEvents = "none";
    overlayGlobal.style.visibility = "hidden";
    Helper.lockBodyScroll(false);
}

/**
 * Sau khi đóng menu Navi+ (open:Search / clickToElement đã skipPrepareMenus): ép tắt overlay,
 * chờ paint — tránh hộp search theme (z-index thấp hơn) hiện dưới lớp phủ một nhịp.
 *
 * @returns {Promise<void>}
 */
Helper.ensureOverlaysDismissedBeforeThemeClick = function () {
    Helper.hideNaviOverlay();
    if (!Helper.hasVisibleSlideMenu()) {
        Helper.hideNaviOverlayGlobal();
    }
    return new Promise(function (resolve) {
        requestAnimationFrame(function () {
            requestAnimationFrame(resolve);
        });
    });
};


Helper.waitForCssToLoad = function(callback, section_setting) {

    // Check đồng bộ trước: nếu CSS đã sẵn sàng thì reveal NGAY (0ms),
    // tránh chờ tới nhịp poll 50ms kế tiếp. Menu hiện ngay trong task của nó (paint trước menu sau).
    var isLoaded = function () {
        return getComputedStyle(document.documentElement)
            .getPropertyValue('--is-navi-css-loaded')
            .trim();
    };

    if (isLoaded()) {
        callback();
        return;
    }

    const checkInterval = setInterval(() => {
        if (isLoaded()) {
            clearInterval(checkInterval); // Dừng kiểm tra khi CSS đã tải
            callback(); // Gọi hàm khi CSS đã tải xong
        }
    }, 50); // Kiểm tra mỗi 50ms để tránh ảnh hưởng hiệu suất
}


// Nếu ko có domain thì sẽ thêm https:// vào đầu url
Helper.standalizeUrl = function(url) {
    if (typeof url !== 'string') return url;

    // Bỏ dấu / đầu và cuối
    const cleanedUrl = url.replace(/^\/+|\/+$/g, '');

    // Lấy phần đầu tiên (trước dấu /)
    const firstSegment = cleanedUrl.split('/')[0];

    // Kiểm tra nếu phần đầu có dấu . và trông giống domain
    const isDomain = /^[a-zA-Z0-9.-]+\.[a-zA-Z]{2,}$/.test(firstSegment);

    // Nếu là domain và chưa có http/https → thêm https://
    if (isDomain && !/^https?:\/\//i.test(url)) {
        return 'https://' + cleanedUrl;
    }

    return url;
}

/*
 * Quét các field name/url/description của một menu item, trả về danh sách
 * các mã ngôn ngữ mà khách đã khai dưới dạng tag <xx:...>.
 * Ví dụ name = "<en:Home><de:Startseite>" → ["en", "de"].
 * Dùng để xác định item này có thực sự là multi-lang hay không, và để
 * validate rằng segment đầu của URL hiện tại đúng là một lang code.
 */
Helper._collectItemLangTags = function(item) {
    if (!item || typeof item !== "object") return [];
    var fields = ["name", "url", "description"];
    var found = {};
    var re = /<([a-zA-Z][a-zA-Z0-9-]*)\s*:/g;
    for (var i = 0; i < fields.length; i++) {
        var v = item[fields[i]];
        if (typeof v !== "string") continue;
        re.lastIndex = 0;
        var m;
        while ((m = re.exec(v)) !== null) {
            found[m[1]] = true;
        }
    }
    return Object.keys(found);
};

/*
 * Chuẩn hoá hostname trước khi so sánh: bỏ "www." đầu, lowercase.
 * Mục đích: coi "myshop.com" và "www.myshop.com" là cùng một host.
 */
Helper._normalizeHost = function(h) {
    return String(h || "").replace(/^www\./i, "").toLowerCase();
};

/*
 * Tự động chèn prefix ngôn ngữ vào URL của menu item nếu visitor đang xem
 * trang ở ngôn ngữ phụ (ví dụ /de/products) và URL trong item chưa có prefix.
 *
 * Điều kiện kích hoạt — phải thoả TẤT CẢ:
 *   1. Item có lang tag trong name/url/description (xác nhận đa ngôn ngữ thật)
 *   2. naviLanguage.currentLanguage() ≠ "localize"
 *   3. Mã ngôn ngữ trên có trong danh sách tag của item (tránh false positive
 *      khi segment đầu của URL không phải là lang code, vd /blog/post-1)
 *   4. URL không phải protocol đặc biệt: tel/sms/mailto/javascript/scroll/
 *      open/share/#anchor
 *   5. URL chưa bắt đầu bằng /{lang}/ hoặc /{lang}
 *   6. Nếu URL absolute → host phải khớp host hiện tại (đã bỏ "www.")
 *
 * Trường hợp đặc biệt được console.log để dev verify khi tính năng kích hoạt.
 */
Helper.localizeUrlByCurrentLang = function(url, item) {
    if (typeof url !== "string" || url === "") return url;

    var langs = Helper._collectItemLangTags(item);
    if (langs.length === 0) return url;

    var lang = naviLanguage.currentLanguage();
    if (lang === "localize") return url;
    if (langs.indexOf(lang) === -1) return url;

    var lower = url.toLowerCase().trim();
    var skipPrefixes = ["tel:", "sms:", "mailto:", "javascript:", "scroll:", "open:", "share:", "#"];
    for (var i = 0; i < skipPrefixes.length; i++) {
        if (lower.indexOf(skipPrefixes[i]) === 0) return url;
    }

    // URL absolute (http://, https://, //) → chỉ xử lý nếu cùng host
    var isAbsolute = /^(https?:)?\/\//i.test(url);
    if (isAbsolute) {
        try {
            var u = new URL(url, document.location.href);
            var sameHost = Helper._normalizeHost(u.hostname) === Helper._normalizeHost(document.location.hostname);
            if (!sameHost) return url;

            if (u.pathname === "/" + lang || u.pathname.indexOf("/" + lang + "/") === 0) return url;

            var newPath = u.pathname.charAt(0) === "/" ? u.pathname : "/" + u.pathname;
            u.pathname = "/" + lang + newPath;
            var out = u.toString();
            // Gate log dev-verify qua navidebug (chỉ in khi localStorage.debug=1)
            navidebug.log("[Navi+ i18n-link] absolute same-host: " + url + " => " + out);
            return out;
        } catch (e) {
            return url;
        }
    }

    // URL tương đối — chuẩn hoá leading slash trước khi check để tránh false miss
    // với URL dạng "en/collections/..." (không có "/" đầu)
    var path = url.charAt(0) === "/" ? url : "/" + url;
    if (path === "/" + lang || path.indexOf("/" + lang + "/") === 0) return url;
    var localized = "/" + lang + path;
    // Gate log dev-verify qua navidebug (chỉ in khi localStorage.debug=1)
    navidebug.log("[Navi+ i18n-link] relative: " + url + " => " + localized);
    return localized;
};




Helper.MultiSite.checkDomainMatch = function(multiSitesString) {
  if (!multiSitesString) return false;

    const sites = multiSitesString
    .split(/[,;|\s]+/)
    .map(s => s.trim()
                .toLowerCase()
                .replace(/^https?:\/\//, '')   // bỏ http:// hoặc https://
                .replace(/^www\./, '')         // bỏ www.
                .replace(/\/+$/, '')           // bỏ dấu / cuối
                .replace(/^www\./, '')         // bỏ lại www nếu nó xuất hiện sau bước trước (phòng trường hợp www xuất hiện sau https)
    )
    .filter(s => s.length > 0);


  if (sites.length === 0) return false;

  const currentDomain = window.location.hostname
    .toLowerCase()
    .replace(/^www\./, '')
    .trim();

  return sites.some(pattern => {

    if (pattern.startsWith('*.')) {
      const base = pattern.slice(2);
      const matched = currentDomain.endsWith('.' + base);
      return matched;
    } else {
      const matched = currentDomain === pattern;
      return matched;
    }
  });
};

Helper.waitForVar__Loaded_SF = function(embedId, callback, maxRetry = 250, delay = 100) {
    const MAX_WAITING_SECONDS = 5;
    let retryCount = 0;
    const cssVarName = `--loaded-${embedId}`;
    const startTime = Date.now();

    function check() {
        const val = getComputedStyle(document.documentElement)
            .getPropertyValue(cssVarName)
            .trim();

        const elapsedSeconds = (Date.now() - startTime) / 1000;

        if (val === '1') {
            callback(); // Gọi hàm khi sẵn sàng
        } else if (elapsedSeconds >= MAX_WAITING_SECONDS) {
            navidebug.log(`⏱️ Timeout after ${MAX_WAITING_SECONDS}s: ${cssVarName} not loaded, executing callback anyway.`);
            callback(); // Nhắm mắt gọi callback luôn
        } else if (retryCount < maxRetry) {
            retryCount++;
            setTimeout(check, delay);
        } else {
            navidebug.warn(`⏱️ Timeout: ${cssVarName} not loaded after ${maxRetry} retries.`);
        }
    }

    check();
}

Helper.HTML.addLoadedFSAtBodyEnd = function(html, delay = 100) {
  function insert() {
    setTimeout(() => {
      document.body.insertAdjacentHTML('beforeend', html);
    }, delay);
  }

  if (document.readyState === 'complete') {
    insert(); // trang đã load xong
  } else {
    window.addEventListener('load', insert); // chờ toàn bộ trang load xong
  }
}

