if (!window.fixGoogleAppInitialized) {
    window.fixGoogleAppInitialized = true;
    const fix = new FixGoogleApp();

    window.addEventListener('load', () => {
        setTimeout(() => fix.apply('.naviItem'), 1000);
    });
}

