          var _rtTotalH = Menu.Sticky.sumItemSlotPx(dragdrop, parseInt(setting['height']) + 8, setting);
          addHtml += cssNaviPrefix + ' { width: ' + setting['height'] + 'px; left: initial; right: 0px; height: ' + _rtTotalH + 'px } ';
