        var fakeHdrCloseStart = menu.querySelector(".slide-horizontal-header-level3");
        if (fakeHdrCloseStart) fakeHdrCloseStart.style.setProperty("border-left", "1px solid var(--navi-slide-h-panel-separator)", "important");

