/******************************************************************************************/

var callPublicFunction = function (functionName, context /*, args */) {
    var args = Array.prototype.slice.call(arguments, 2);
    var namespaces = functionName.split(".");
    var func = namespaces.pop();
    for(var i = 0; i < namespaces.length; i++) {
        context = context[namespaces[i]];
    }
    if(typeof context[func] === "function") {
        return context[func].apply(context, args);
    } else {
        //navidebug.log("Function not found: " + functionName);
    }
};

/**
 * ================= Navi+ Scroll Toggle =================
 * Bộ hàm điều khiển Tabbar/Menu dựa trên hướng scroll:
 * 
 * - scrollToHide:   Vào trang đang HIỆN. 
 *                   Scroll xuống -> ẨN, scroll lên -> HIỆN.
 *                   (Thích hợp cho tabbar đáy màn hình)
 * 
 * - scrollToShow:   Vào trang đang ẨN.
 *                   Scroll xuống -> HIỆN, scroll lên -> ẨN.
 *                   (Logic ngược với scrollToHide, 
 *                    thường dùng cho nút action, back-to-top, v.v.)
 * 
 * Điểm chung:
 *  - Tự động thêm CSS transition để ẩn/hiện mượt bằng transform+opacity.
 *  - Hysteresis 20px để tránh rung giật.
 *  - Có check mobile/desktop screen.
 *  - Vẫn tương thích với naviman_version == "simulator".
 * 
 * Lưu ý:
 *  - Nếu tabbar nằm trên cùng màn hình, đổi CSS translateY(100%) thành translateY(-100%).
 *  - Có thể thay đổi thời gian transition (.22s) hoặc hysteresis (20px) theo ý muốn.
 * 
 * Bổ sung:
 *  - Khi behavior = "downShow" (autoShow):
 *      + Nếu cách top < 3px thì menu sẽ LUÔN luôn ẨN.
 *      + Nếu cách bottom < 3px thì menu sẽ LUÔN luôn HIỆN.
 *  - Khi behavior = "downHide" (autoHide):
 *      + Nếu cách top < 3px thì menu sẽ LUÔN luôn HIỆN.
 *      + Nếu cách bottom < 3px thì menu sẽ LUÔN luôn ẨN.
 */

// Các biến cấu hình
const HYSTERESIS = 20;  // px biên tránh rung
const EDGE_LOCK = 3;    // px: biên khóa ở top/bottom

// Hàm chung nội bộ (không gọi trực tiếp)
var _scrollToggle = function (screen, selector, behavior, initial) {
    
    if (typeof naviman_version !== "undefined" && naviman_version === "simulator") return;

    var isMobile = Helper.Env.isOnMobile();
    if ((isMobile && screen === "desktop") || (!isMobile && screen === "mobile")) return;


    let obj = selector.startsWith('.') ? document.getElementsByClassName(selector.substr(1))[0]
        : selector.startsWith('#') ? document.getElementById(selector.substr(1))
            : document.querySelector(selector);
    if (!obj) return;

    obj.classList.add("navi-anim");
    if (initial === "hide") obj.classList.add("navi-hidden"); else obj.classList.remove("navi-hidden");
    let hidden = obj.classList.contains("navi-hidden");

    const hide = () => { if (!hidden) { obj.classList.add("navi-hidden"); hidden = true; } };
    const show = () => { if (hidden) { obj.classList.remove("navi-hidden"); hidden = false; } };

    let lastY = window.pageYOffset || document.documentElement.scrollTop || 0;

    window.addEventListener("scroll", () => {
        const curY = window.pageYOffset || document.documentElement.scrollTop || 0;
        const maxScroll = document.documentElement.scrollHeight - window.innerHeight;

        // ================= AutoShow =================
        if (behavior === "downShow") {
            // Nếu ở gần top -> luôn ẩn
            if (curY <= EDGE_LOCK) {
                hide();
                lastY = curY;
                return;
            }
            // Nếu ở gần bottom -> luôn hiện
            if ((maxScroll - curY) <= EDGE_LOCK) {
                show();
                lastY = curY;
                return;
            }
        }

        // ================= AutoHide =================
        if (behavior === "downHide") {          
  
            // Nếu ở gần top -> luôn hiện
            if (curY <= EDGE_LOCK) {
                show();
                lastY = curY;
                return;
            }
            // Nếu ở gần bottom -> luôn ẩn
            if ((maxScroll - curY) <= EDGE_LOCK) {
                hide();
                lastY = curY;
                return;
            }
        }

        // ================= Scroll detection =================
        if (curY > lastY + HYSTERESIS) { // scroll xuống
            (behavior === "downHide" ? hide : show)();
            lastY = curY;
        }
        else if (curY < lastY - HYSTERESIS) { // scroll lên
            (behavior === "downHide" ? show : hide)();
            lastY = curY;
        }
    }, { passive: true });
};

/**
 * scrollToHide:
 *  - Vào trang: menu HIỆN.
 *  - Scroll xuống: ẨN.
 *  - Scroll lên: HIỆN.
 */
var scrollToHide = function(screen, cssNaviPrefix){
  _scrollToggle(screen, cssNaviPrefix.trim(), "downHide", "show");
};

/**
 * scrollToShow:
 *  - Vào trang: menu ẨN.
 *  - Scroll xuống: HIỆN.
 *  - Scroll lên: ẨN.
 */
var scrollToShow = function(screen, cssNaviPrefix){
  _scrollToggle(screen, cssNaviPrefix.trim(), "downShow", "hide");
};
/* ================= Navi+ Scroll Toggle ================= */


var openInbox_loopHideChat = function () {
    var isLoop = true;

    var shopifyChatEl = document.querySelector('#ShopifyChat');
    if (shopifyChatEl != null) {
        if( shopifyChatEl.getAttribute("is-open") == "false" )
            if( shopifyChatEl.style.visibility == "visible" ) {
                shopifyChatEl.style.visibility = "hidden";
                isLoop = false;
            }
    } else {
        isLoop = false;
    }

    callbackPublicFunc(openInbox_loopHideChat);

    if( isLoop ) {
        setTimeout(function () {
            openInbox_loopHideChat();
        }, 200);
    }
};

var openInbox_loopHideFAB = function () {
    var isLoop = true;

    var shopifyChatEl = document.querySelector('#ShopifyChat');
    if (shopifyChatEl != null) {
        shopifyChatEl.style.visibility = "hidden";
        isLoop = false;
    }

    if (isLoop) {
        setTimeout(function () {
            openInbox_loopHideFAB();
        }, 200);
    }
};

/**
 * Reset visibility Shopify Inbox nếu platform hiện tại không nên bị ẩn bởi open:Inbox.
 *
 * - Trên mobile: nếu menu đang ẨN (hasMobile == false) thì đảm bảo Shopify Inbox hiển thị.
 * - Trên desktop: nếu menu đang ẨN (hasDesktop == false) thì đảm bảo Shopify Inbox hiển thị.
 *
 * @param {boolean} hasMobile  Menu được bật hiển thị trên mobile hay không (setting mobileDisplay)
 * @param {boolean} hasDesktop Menu được bật hiển thị trên desktop hay không (setting desktopDisplay)
 */
var resetShopifyInboxVisibilityForPlatform = function (hasMobile, hasDesktop) {
    var shopifyChatEl = document.querySelector('#ShopifyChat');
    if (!shopifyChatEl) return;

    var shouldShow = false;

    if (Helper.Env.isOnMobile() && !hasMobile) shouldShow = true;
    if (!Helper.Env.isOnMobile() && !hasDesktop) shouldShow = true;

    if (shouldShow && shopifyChatEl.style.visibility === 'hidden') {
        shopifyChatEl.style.visibility = 'visible';
    }
};

/**
 * Xử lý ẩn/hiện Shopify Inbox khi gặp menu item có url open:Inbox.
 *
 * Logic theo cấu hình:
 *  - Menu chỉ mobile  (hasMobile && !hasDesktop): ẩn Inbox trên mobile, không đụng desktop.
 *  - Menu chỉ desktop (!hasMobile && hasDesktop): ẩn Inbox trên desktop, không đụng mobile.
 *  - Menu cả hai (hasMobile && hasDesktop): ẩn Inbox trên cả mobile + desktop (giữ behavior cũ).
 *  - Nếu menu bị ẩn trên platform hiện tại: đảm bảo Inbox được hiển thị lại (không bị inline style cũ giữ lại).
 *
 * @param {boolean} hasMobile  Menu được bật hiển thị trên mobile hay không (setting mobileDisplay)
 * @param {boolean} hasDesktop Menu được bật hiển thị trên desktop hay không (setting desktopDisplay)
 */
var handleOpenInboxVisibility = function (hasMobile, hasDesktop) {
    var viewportWidth = window.innerWidth || document.documentElement.clientWidth || 0;
    var isMobileViewport = viewportWidth <= Helper.Env.MOBILE_MAX;
    var isDesktopViewport = viewportWidth >= Helper.Env.DESKTOP_MIN;

    var isMobileOnly = hasMobile && !hasDesktop;
    var isDesktopOnly = hasDesktop && !hasMobile;

    var shouldHide = false;

    if (isMobileOnly && isMobileViewport) shouldHide = true;
    else if (isDesktopOnly && isDesktopViewport) shouldHide = true;
    else if (hasMobile && hasDesktop) shouldHide = true;

    if (shouldHide) {
        openInbox_loopHideFAB();
    } else {
        resetShopifyInboxVisibilityForPlatform(hasMobile, hasDesktop);
    }
};

var openInbox = function() {
    if( document.querySelector('#ShopifyChat') == null ) {
        console.log("Navi+: Shopify inbox is not installed. Read document <a target='_blank' href='https://help.naviplus.io/docs/integrations/chat-tools/shopify-inbox/'>here</a>");
    }

    var divMenu = document.querySelector('#ShopifyChat').shadowRoot.querySelector('.chat-toggle');
    document.querySelector('#ShopifyChat').style.visibility = "visible";
    divMenu.addEventListener('click', () => {});
    divMenu.click();

    callbackPublicFunc(openInbox);

    setTimeout(function() {
        openInbox_loopHideChat();
    }, 200);

};

var openInboxWithoutReplace = function() {
    if( document.querySelector('#ShopifyChat') == null ) {
        console.log("Navi+: Shopify inbox is not installed. Read document <a target='_blank' href='https://help.naviplus.io/docs/integrations/chat-tools/shopify-inbox/'>here</a>");
    }

    var divMenu = document.querySelector('#ShopifyChat').shadowRoot.querySelector('.chat-toggle');
    document.querySelector('#ShopifyChat').style.visibility = "visible";
    divMenu.addEventListener('click', () => {});
    divMenu.click();

    callbackPublicFunc(openInboxWithoutReplace);
};

var openShareMe = function(){
    if (navigator.share) {
        navigator.share({
            title: document.title,
            text: "Navi+ share",
            url: window.location.href
        })
            .then(() => navidebug.log('Successful share'))
            .catch(error => navidebug.error('Error sharing:', error));
    }else
    navidebug.log("This device does not support share directly!");

    callbackPublicFunc(openShareMe);
}

/***** Message popup (open:Message) ******************************************************/
var _naviMessageCloseTimer = null;
var _naviMessageCountdownTimer = null;
var _naviMessageOnKeyDown = function (e) { if (e.key === 'Escape') _closeNaviMessagePopup(); };
/* Bấm ra ngoài popup (bất kỳ đâu ngoài #navi-message-popup) -> đóng. Gắn ở capture phase để
   không bị chặn bởi stopPropagation() của handler khác, và gắn TRỄ 1 tick (setTimeout 0) để
   không tự bắt trúng ngay chính cú click đã mở popup (event đang bubble dở khi openMessage chạy). */
var _naviMessageOnDocClick = function (e) {
    var el = document.getElementById('navi-message-popup');
    if (el && !el.contains(e.target)) _closeNaviMessagePopup();
};

var _closeNaviMessagePopup = function () {
    if (_naviMessageCloseTimer) { clearTimeout(_naviMessageCloseTimer); _naviMessageCloseTimer = null; }
    if (_naviMessageCountdownTimer) { clearInterval(_naviMessageCountdownTimer); _naviMessageCountdownTimer = null; }
    document.removeEventListener('keydown', _naviMessageOnKeyDown);
    document.removeEventListener('click', _naviMessageOnDocClick, true);
    var el = document.getElementById('navi-message-popup');
    if (!el) return;
    el.classList.remove('show');
    setTimeout(function () { if (el.parentNode) el.parentNode.removeChild(el); }, 300);
};

/*
 * openMessage(text, durationSec)
 * Trượt lên 1 popup từ đáy màn hình (z-index cao nhất, đủ cao để phủ hết STICKY_TABBAR cả
 * mobile lẫn desktop — desktop thu hẹp về sheet căn giữa qua CSS media query) nền trắng, icon
 * chuông (Remix Icon `ri-notification-3-line`, font đã load sẵn toàn FE) + thông điệp. Đếm
 * 1/N -> 2/N -> .. -> N/N trong N giây (durationSec, mặc định 3 nếu không truyền/không hợp lệ)
 * rồi tự đóng (trượt xuống). Đóng sớm bằng nút x, phím ESC, hoặc bấm ra ngoài popup. Gọi lại
 * khi đang có popup khác hiển thị -> đóng cái cũ ngay, hiện cái mới.
 */
var openMessage = function (text, durationSec) {
    _closeNaviMessagePopup();

    var DURATION_SEC = (typeof durationSec === "number" && !isNaN(durationSec) && durationSec > 0) ? Math.round(durationSec) : 3;
    var count = 1;

    var wrap = document.createElement('div');
    wrap.id = 'navi-message-popup';

    var closeBtn = document.createElement('button');
    closeBtn.type = 'button';
    closeBtn.className = 'navi-message-close';
    closeBtn.innerHTML = '&times;';
    closeBtn.onclick = function (e) { e.stopPropagation(); _closeNaviMessagePopup(); };

    var iconEl = document.createElement('i');
    iconEl.className = 'navi-message-icon ri-notification-3-line';

    var textEl = document.createElement('div');
    textEl.className = 'navi-message-text';
    textEl.textContent = text;

    var countEl = document.createElement('div');
    countEl.className = 'navi-message-count';
    countEl.textContent = count + '/' + DURATION_SEC;

    wrap.appendChild(closeBtn);
    wrap.appendChild(iconEl);
    wrap.appendChild(textEl);
    wrap.appendChild(countEl);
    document.body.appendChild(wrap);

    setTimeout(function () { wrap.classList.add('show'); }, 10);

    document.addEventListener('keydown', _naviMessageOnKeyDown);
    setTimeout(function () { document.addEventListener('click', _naviMessageOnDocClick, true); }, 0);

    _naviMessageCountdownTimer = setInterval(function () {
        count++;
        if (count > DURATION_SEC) {
            clearInterval(_naviMessageCountdownTimer);
            _naviMessageCountdownTimer = null;
            return;
        }
        countEl.textContent = count + '/' + DURATION_SEC;
    }, 1000);

    _naviMessageCloseTimer = setTimeout(_closeNaviMessagePopup, DURATION_SEC * 1000);

    callbackPublicFunc(openMessage);
};


var callbackPublicFunc = function(func, embedID = "") {
    let callbackName = `Navi.${func.name}_Callback`;

    if (window.Navi)
    {
        if (typeof eval(callbackName) === 'function') {
            eval(callbackName + '("'+ embedID +'")' );
            navidebug.log('Executed: '+ `${callbackName}` + '("'+ embedID +'") ');
        } else {
            // navidebug.log(`${callbackName} is not found!`);
        }
    }else
    navidebug.log(`The function ${callbackName} is not defined.`);
}

var callbackPublicFunc_delay = function(func, embedID = "") {
    setTimeout(() => { callbackPublicFunc(func, embedID); }, 500);
}

function goBack() {
    window.history.back();
}

function goForward() {
    window.history.forward();
}

/*
 * appendSlideMenuTo(cssSelector, slideMenuEmbedID, color, is_boxed)
 * Tìm phần tử logo qua cssSelector, thêm class naviplus_slide_icon để hiện icon hamburger
 * bằng CSS ::before, rồi gán click → openNaviMenu(slideMenuEmbedID).
 *
 * - Nếu gọi sớm (logo chưa có trong DOM): tự chờ bằng MutationObserver, gắn đúng 1 lần khi xuất hiện.
 * - Idempotent: gọi nhiều lần cũng không bị trùng.
 * - CSS base inject 1 lần, CSS per-instance inject theo class riêng của (embedID + settings).
 *   Nhiều selector cùng menu có thể dùng boxed/color/side khác nhau mà không bị xung đột.
 *
 * Mỗi logo element nhận 2 class:
 *   naviplus_slide_icon                         — style chung (::before hamburger)
 *   naviplus_slide_icon_<embedID>_<settingsKey> — scope riêng cho màu, boxed, side
 *
 * @param {string}  cssSelector      - CSS selector trỏ đến phần tử chứa logo
 * @param {string}  slideMenuEmbedID - ID của .naviItem.CONTEXT_SLIDE (có hoặc không có # . đều được)
 * @param {string}  [color]          - Màu icon: "#FFF", "FFF", "#FAFAFA", "rgba(...)" — mặc định đen
 * @param {boolean} [is_boxed=false] - true: bọc icon trong box vuông 28×28, icon thu nhỏ 20×20 cách lề 4px
 * @param {string}  [side='left']    - Vị trí icon: "left" (mặc định) hoặc "right"
 *
 * -----------------------------------------------------------------------
 * Nếu KHÔNG muốn dùng hàm này (không cần event, chỉ cần icon hiển thị),
 * có thể copy CSS sau vào theme (thay .your-logo-selector bằng selector thực tế):
 *
 * Mode thường:
 *   .your-logo-selector {
 *     position: relative;
 *     cursor: pointer;
 *     padding-left: 32px !important;
 *     color: #000; /* hoặc màu tùy chọn *\/
 *   }
 *   .your-logo-selector::before {
 *     content: '';
 *     display: block;
 *     position: absolute;
 *     left: 0;
 *     top: 50%;
 *     transform: translateY(-50%);
 *     width: 18px;
 *     height: 2px;
 *     background: currentColor;
 *     box-shadow: 0 6px 0 currentColor, 0 -6px 0 currentColor;
 *     transition: opacity 0.2s;
 *   }
 *
 * Mode boxed (is_boxed=true):
 *   .your-logo-selector {
 *     position: relative;
 *     cursor: pointer;
 *     padding-left: 36px !important;
 *     color: #000;
 *   }
 *   .your-logo-selector::before {
 *     content: '';
 *     display: block;
 *     position: absolute;
 *     left: 0;
 *     top: 50%;
 *     transform: translateY(-50%);
 *     width: 14px;
 *     height: 2px;
 *     background: currentColor;
 *     box-shadow: 0 5px 0 currentColor, 0 -5px 0 currentColor,
 *                 -4px -9px 0 0 currentColor, 18px -9px 0 0 currentColor,
 *                 -4px 9px 0 0 currentColor,  18px 9px 0 0 currentColor,
 *                 -4px 0 0 0 currentColor,    18px 0 0 0 currentColor;
 *   }
 *   /* Cách đơn giản hơn: dùng outline + padding trên ::before *\/
 *
 * -----------------------------------------------------------------------
 */
var appendSlideMenuTo = function(cssSelector, slideMenuEmbedID, color, is_boxed, side, device) {
    slideMenuEmbedID = slideMenuEmbedID.replace(/^[#.]/, "");

    /* Chuẩn hóa device: "D" = desktop only, "M" = mobile only, khác = cả hai */
    var deviceFilter = (device === "D" || device === "M") ? device : "both";

    /* Chuẩn hóa color: "FFF" → "#FFF", undefined → null (dùng currentColor) */
    var iconColor = null;
    if (color && typeof color === "string" && color.trim() !== "") {
        iconColor = color.trim();
        if (iconColor.charAt(0) !== "#" && !iconColor.startsWith("rgb") && !iconColor.startsWith("hsl")) {
            iconColor = "#" + iconColor;
        }
    }

    var boxed = is_boxed === true;
    var align = (side === "right") ? "right" : "left";

    /* CSS base: inject 1 lần dùng chung — chỉ định vị trí, không định màu */
    var baseStyleId = "navi-hamburger-style";
    if (!document.getElementById(baseStyleId)) {
        var baseCss = `
            .naviplus_slide_icon {
                position: relative;
                cursor: pointer;
            }
            .naviplus_slide_icon::before {
                content: '';
                display: block;
                position: absolute;
                top: 50%;
                transform: translateY(-50%);
                transition: opacity 0.2s;
            }
        `;
        var baseEl = document.createElement("style");
        baseEl.id = baseStyleId;
        baseEl.textContent = baseCss;
        document.head.appendChild(baseEl);
    }

    /* CSS per-instance: keyed theo settings (embedId + boxed + align + color)
     * để nhiều selector cùng menu có thể dùng style khác nhau mà không bị ghi đè. */
    var colorKey = iconColor ? iconColor.replace(/[^a-zA-Z0-9]/g, "") : "def";
    var settingsKey = slideMenuEmbedID + "_" + (boxed ? "b" : "n") + "_" + align + "_" + colorKey;
    var instanceStyleId = "navi-hamburger-style-" + settingsKey;
    if (!document.getElementById(instanceStyleId)) {
        var instanceClass = ".naviplus_slide_icon_" + settingsKey;
        var color_val = iconColor || "currentColor";

        var instanceCss;
        if (boxed) {
            /* Boxed: box 28×28, icon 14px rộng, 3 đường cách nhau 5px, cách lề 4px 4 phía */
            instanceCss = `
                ${instanceClass} {
                    padding-${align}: 36px !important;
                }
                ${instanceClass}::before {
                    ${align}: 0;
                    width: 28px;
                    height: 28px;
                    background: transparent;
                    outline: 2px solid ${color_val};
                    border-radius: 3px;
                    box-shadow: none;
                }
                ${instanceClass}::after {
                    content: '';
                    display: block;
                    position: absolute;
                    ${align}: 7px;
                    top: 50%;
                    transform: translateY(-50%);
                    width: 14px;
                    height: 2px;
                    background: ${color_val};
                    box-shadow: 0 5px 0 ${color_val}, 0 -5px 0 ${color_val};
                    transition: opacity 0.2s;
                }
            `;
        } else {
            /* Normal: icon 18px, 3 đường cách nhau 6px */
            instanceCss = `
                ${instanceClass} {
                    padding-${align}: 32px !important;
                }
                ${instanceClass}::before {
                    ${align}: 0;
                    width: 18px;
                    height: 2px;
                    background: ${color_val};
                    box-shadow: 0 6px 0 ${color_val}, 0 -6px 0 ${color_val};
                }
            `;
        }

        var instanceEl = document.createElement("style");
        instanceEl.id = instanceStyleId;
        instanceEl.textContent = instanceCss;
        document.head.appendChild(instanceEl);
    }

    /* CSS device filter: inject 1 lần cho D và 1 lần cho M — hide icon bằng media query khi resize.
     * Dùng class naviplus_slide_icon_device_D / _M thay vì skip JS hoàn toàn để resize tự cập nhật. */
    var deviceStyleId = "navi-hamburger-style-device-" + deviceFilter;
    if (deviceFilter !== "both" && !document.getElementById(deviceStyleId)) {
        var deviceCss = deviceFilter === "D"
            /* Desktop only: ẩn icon trên mobile (≤768px) */
            ? "@media (max-width:768px){.naviplus_slide_icon_device_D{padding-left:0!important;padding-right:0!important}.naviplus_slide_icon_device_D::before,.naviplus_slide_icon_device_D::after{display:none!important}}"
            /* Mobile only: ẩn icon trên desktop (>768px) */
            : "@media (min-width:769px){.naviplus_slide_icon_device_M{padding-left:0!important;padding-right:0!important}.naviplus_slide_icon_device_M::before,.naviplus_slide_icon_device_M::after{display:none!important}}";
        var deviceEl = document.createElement("style");
        deviceEl.id = deviceStyleId;
        deviceEl.textContent = deviceCss;
        document.head.appendChild(deviceEl);
    }

    /* Gắn class + event vào logo element — chỉ gắn 1 lần */
    var _bind = function(logoEl) {
        if (logoEl._naviHamburgerBound) return;
        logoEl._naviHamburgerBound = true;

        /* ::before không hoạt động trên replaced elements (img, input, video...).
         * Leo lên parentElement để gắn — đánh dấu img gốc để không gắn trùng lần sau. */
        var REPLACED = { IMG: 1, INPUT: 1, VIDEO: 1, IFRAME: 1, CANVAS: 1, EMBED: 1 };
        if (REPLACED[logoEl.tagName] && logoEl.parentElement) {
            navidebug.log("appendSlideMenuTo: " + logoEl.tagName + " là replaced element, gắn vào parentElement thay");
            logoEl = logoEl.parentElement;
            if (logoEl._naviHamburgerBound) return;
            logoEl._naviHamburgerBound = true;
        }

        logoEl.classList.add("naviplus_slide_icon");
        logoEl.classList.add("naviplus_slide_icon_" + settingsKey);
        /* Đánh dấu device để CSS media query tự hide/show khi resize */
        if (deviceFilter !== "both") logoEl.classList.add("naviplus_slide_icon_device_" + deviceFilter);

        logoEl.addEventListener("click", function(e) {
            /* Guard device: không mở menu khi icon đang ẩn theo device filter (mobile với D,
               desktop với M) → cho click rơi xuống hành vi mặc định (logo điều hướng). */
            if (deviceFilter === "D" && Helper.Env.isOnMobile()) return;
            if (deviceFilter === "M" && !Helper.Env.isOnMobile()) return;

            /* CHỈ mở slide khi click rơi vào DẢI ICON (phần padding chứa ≡ ở cạnh align),
               KHÔNG mở khi bấm vào phần logo thật → giữ được link về trang chủ.
               Lấy bề rộng dải icon = padding thực (computed) → tự đúng theo device: media query
               (D)/(M) reset padding=0 trên thiết bị ẩn icon → zone=0 → toàn logo đều điều hướng. */
            var cs = window.getComputedStyle(logoEl);
            var zoneW = parseFloat(align === "right" ? cs.paddingRight : cs.paddingLeft) || 0;
            var rect = logoEl.getBoundingClientRect();
            var inIconZone = (align === "right")
                ? (e.clientX >= rect.right - zoneW)
                : (e.clientX <= rect.left + zoneW);
            if (!inIconZone) return; // bấm vào logo → để điều hướng bình thường

            e.preventDefault();
            e.stopPropagation();
            openNaviMenu(slideMenuEmbedID);
        });

        navidebug.log("appendSlideMenuTo: gắn vào", cssSelector, "→ mở #" + slideMenuEmbedID, { color: iconColor, boxed: boxed, side: align, device: deviceFilter });
    };

    var logoEl = document.querySelector(cssSelector);
    if (logoEl) {
        _bind(logoEl);
        return;
    }

    /* Logo chưa có trong DOM — dùng MutationObserver để chờ */
    navidebug.log("appendSlideMenuTo: chờ selector", cssSelector);
    var observer = new MutationObserver(function() {
        var el = document.querySelector(cssSelector);
        if (!el) return;
        observer.disconnect();
        _bind(el);
    });
    observer.observe(document.body || document.documentElement, { childList: true, subtree: true });

};

// TASK00016. Begin
/* Đóng menu bằng phím ESC — chỉ áp dụng trên desktop (innerWidth > 768).
 *
 * Slide menu (CONTEXT_SLIDE):
 *   - slide-horizontal có level 3 → closeLevel3 (về level 2)
 *   - slide-horizontal có level 2 → closeLevel2 (về level 1)
 *   - chỉ level 1 hoặc menu khác → đóng toàn bộ
 *
 * Tabbar / FAB / Mega (non-slide):
 *   - level 3 mở → hideAllLevel3Items (về level 2)
 *   - level 2 mở (không có 3) → closeByOverlayGlobalForNonSlideMenus (về level 1)
 */
document.addEventListener("keydown", function(e) {
    if (e.key !== "Escape") return;
    /* TASK00658: listener TOÀN CỤC (không gắn menu nào) nên không dùng được ngưỡng per-menu trực tiếp.
       Vẫn thoát sớm ở mobile như cũ, TRỪ khi có Desktop Mega Menu đang ở chế độ desktop nhờ
       breakpoint riêng — lúc đó dropdown desktop của nó đang mở được thì ESC phải đóng được. */
    if (Helper.Env.isOnMobile() && !Helper.Env.hasMegaMenuInDesktopMode()) return;

    /* --- Slide menus (CONTEXT_SLIDE) --- */
    var slideClasses = [
        "hamburger-left-right",
        "hamburger-right-left",
        "hamburger-top-down",
        "hamburger-down-top",
        "hamburger-fullscreen",
        "hamburger-fullpopup"
    ];
    var selector = slideClasses.map(function(c) { return "." + c; }).join(",");
    var openSlides = document.querySelectorAll(selector);

    openSlides.forEach(function(element) {
        if (getComputedStyle(element).visibility !== "visible") return;
        e.preventDefault();

        if (element.getAttribute("ui") === "slide-horizontal") {
            var closedLevel = false;
            if (Menu.Context.Horizontal.getOpenedSubmenu(element, "3")) {
                navidebug.log("[ESC] slideH closeLevel3 | id=" + element.id);
                Menu.Context.Horizontal.closeLevel3(element);
                closedLevel = true;
            } else if (Menu.Context.Horizontal.getOpenedSubmenu(element, "2")) {
                navidebug.log("[ESC] slideH closeLevel2 | id=" + element.id);
                Menu.Context.Horizontal.closeLevel2(element);
                closedLevel = true;
            }
            if (closedLevel) return;
        }

        navidebug.log("[ESC] slide close menu | id=" + element.id);
        var _setting = (typeof getSettingOfNaviman === "function") ? getSettingOfNaviman(element.id) : {};
        var _dur = (typeof Animation !== "undefined" && Animation.getDuration)
            ? Animation.getDuration(_setting ? _setting["animationSpeed"] : undefined)
            : 300;
        Animation.hamburgerClose(element, {
            durationMs: _dur,
            animStyle: (_setting && _setting["animationStyle"]) || "",
            doneCallback: function() {
                Helper.hideNaviOverlayGlobal();
                Helper.hideNaviOverlay();
            }
        });
    });

    /* --- Non-slide menus (Tabbar, FAB, Mega): kiểm tra level 3/2 ngoài CONTEXT_SLIDE --- */
    var nonSlideLevel3 = Array.from(document.querySelectorAll(".naviman_app li.menu-expand-level2"))
        .filter(function(li) { return !li.closest(".CONTEXT_SLIDE"); });
    var nonSlideLevel2 = Array.from(document.querySelectorAll(".naviman_app li.menu-expand-level1"))
        .filter(function(li) { return !li.closest(".CONTEXT_SLIDE"); });

    if (nonSlideLevel3.length > 0) {
        e.preventDefault();
        navidebug.log("[ESC] non-slide hideAllLevel3Items");
        naviman.hideAllLevel3Items();
    } else if (nonSlideLevel2.length > 0) {
        e.preventDefault();
        navidebug.log("[ESC] non-slide closeByOverlayGlobal");
        Finalizer.Event.closeByOverlayGlobalForNonSlideMenus();
    }

    /* Blur phần tử đang focus trong naviman để tránh browser hiện focus outline sau ESC */
    var _active = document.activeElement;
    if (_active && _active.closest && _active.closest(".naviman_app, .navi-hambuger-overlay-trigger, .navi-hambuger-overlay")) {
        _active.blur();
    }
});
// TASK00016. End


    var asyncGetCart = async function(opts) {
    var forceFetch = opts && opts.forceFetch;
    if (!forceFetch && window.NaviEnv && typeof window.NaviEnv.cartItem !== 'undefined') {
        // console.log('Cart count loaded from NaviEnv.cartItem');
        return { item_count: window.NaviEnv.cartItem };
    }

    const result = await fetch(window.Shopify.routes.root + 'cart.json');

    if (result.status === 200) {
        var data = await result.json();
        if (window.NaviEnv && typeof data.item_count !== 'undefined') {
            window.NaviEnv.cartItem = data.item_count;
        }
        return data;
    }
    throw new Error(`Failed to get request, Shopify returned ${result.status} ${result.statusText}`);
};

var updateCartCount = function( item_count ) {
    setCartCount(item_count);
    // Todo 19/6: Chỗ này cần test kỹ càng, ko work rồi vì nếu trộn lẫn thì sẽ ko chạy
    var isHideBadge = false;
    var span = document.querySelectorAll('li.item_badge_withcount span.cart_count');
    for (var i = 0; i < span.length; i++) {
        span[i].textContent = item_count;
        if( item_count == 0 ) {
            span[i].style.display = "none";
            isHideBadge = true;
        }
        else
            span[i].style.display = "initial";
    }

    var span = document.querySelectorAll('li.child_badge_withcount span.cart_count');
    for (var i = 0; i < span.length; i++) {
        span[i].textContent = item_count;
        if( item_count == 0 ) {
            span[i].style.display = "none";
            isHideBadge = true;
        }
        else
            span[i].style.display = "initial";
    }

    if( item_count == 0 ) {
        document.documentElement.style.setProperty('--cart-count-number', '');
    }else {
        document.documentElement.style.setProperty('--cart-count-number', `"${item_count}"`);
    }

    const root = document.querySelector(":root");
    if( isHideBadge )
        root.style.setProperty("--cart-count-text", '""');
    else
        root.style.setProperty("--cart-count-text", '"●"');

    callbackPublicFunc(updateCartCount);
};

var checkAndUpdateCartCount = function() {
    asyncGetCart({ forceFetch: true }).then(function(result) {
        updateCartCount(result.item_count);
    });
};

var setCartCount =  function(count)
{
    cartCount = count;
};

