BaseWidth._el = null;         // element khung đã dò được (nguồn sự thật cho ResizeObserver)
BaseWidth._ro = null;
BaseWidth._subs = [];
BaseWidth._lastLogSig = null;   // chỉ log khi kết quả đổi, tránh ngập console

