    minHeight: 8,
    centerTol: 4,         // lệch tâm tối đa vẫn coi là căn giữa
    fullBleedTol: 12,     // width >= viewport - 12 coi là full-bleed
    clusterTol: 3,
    maxNodes: 4000,       // trần số node duyệt mỗi vùng (chặn hiệu năng máy yếu)
    maxDepth: 16,
