            // (cũng được gọi từ gotoUrl() cho leaf-click bubble lên, không chỉ click ra ngoài menu này).
            navidebug.log("[SlideMenu] handleTouchOutsideAllMenus → closeCurrentOpeningSubmenu | target=" + event.target.tagName + (event.target.className ? "." + String(event.target.className).trim().split(/\s+/)[0] : ""));
            var _hOpen = (typeof naviman !== "undefined" && naviman.Helper) || (typeof Helper !== "undefined" ? Helper : null);
