var Finalizer = Finalizer || {}


if (!window._navimanCallFinalizerOneTimeOnly) {
    window._navimanCallFinalizerOneTimeOnly = true;

    /*
     * Đăng ký ngay, không cần chờ window.load
     *
     * handleTouchOutsideSlideMenu chỉ dùng document.addEventListener("click").
     * Event listener trên document không cần DOM hay bất kỳ element nào tồn tại
     * lúc đăng ký — click chỉ xảy ra khi user thực sự bấm, lúc đó NaviPlus đã
     * chạy xong (bằng chứng: slide menu đã mở được thì Animation, naviman.Helper,
     * ZIndex đều đã sẵn sàng).
     *
     * Lý do PHẢI đăng ký sớm (không chờ window.load):
     *   User có thể bấm trigger mở slide menu TRƯỚC KHI page load xong
     *   (ví dụ: đang còn _navi_loading). Nếu handler chưa được đăng ký,
     *   hamburger_close và naviman_app_overlay_global sẽ không đóng được menu
     *   cho đến tận khi window.load fires — trải nghiệm tệ.
     *
     * handleTouchBackButtonOnSlideMenuHorizontal cũng dùng document.addEventListener
     * với capture:true — cùng lý do, đăng ký sớm là an toàn.
     */
    Finalizer.Event.handleTouchOutsideSlideMenu();
    Finalizer.Event.handleTouchBackButtonOnSlideMenuHorizontal();

    window.addEventListener("load", function() {

        /* Xử lý hover chuột với desktop qua class */
        Finalizer.Desktop.handleHoverMenu();

        /* Fix cho việc chỉ hiện 1 ul navigation duy nhất khi hover */
        Finalizer.Optimize.fixOnlyOneULNavigation();

        /* Fix cho việc bấm vào ngoài menu thì đóng menu vào */
        Finalizer.Event.handleTouchOutsideAllMenus();

        /* Căn chỉnh "Under text" divider: đo vị trí .info thực tế sau khi render */
        Finalizer.Optimize.fixDividerUnderText();
    });

} // End of click out of menu

